```c
#ifndef FT_PRINTF_H
# define FT_PRINTF_H

/*printf에서 사용할 함수들을 macro로 설정해주었습니다. */
/*이 당시엔 enum을 몰라서 이렇게 구현을 했습니다..*/

# define F_WDTH 64
# define F_PREC 32
# define F_ZERO 16
# define F_LEFT 8
# define F_PLUS 4
# define F_SHAP 2
# define F_SPACE 1

# include <stdarg.h>
# include <unistd.h>

/*specifier 문자를 만났을 때, 어떻게 출력을 해야되는지에 대한 정보를 저장할 구조체입니다.*/

typedef struct s_info
{
	unsigned int	flag; /*이 변수에 flag 정보를 비트연산으로 저장합니다.*/
	int				field[2]; # width/precision 값 저장 (field[0]=width, field[1]=precision)
	int				cnt; /*specifier 문자를 처리할 때, 출력하는 문자의 갯수를 저장합니다.*/
	char			cmd; /*어떤 specifier를 처리하는지 저장합니다.*/
}	t_info;

int	ft_printf(const char *s, ...);
int	ft_putchr(char c, t_info *i);
int	ft_printstr(char *s, t_info *i);
int	ft_putnum(long long num, t_info *i, int cur);
int	ft_puthex(unsigned long long n, t_info *i, int cur);
int	ft_max(int a, int b);
int	ft_padding(t_info *i, int n);
int	ft_precision(t_info *i, int num, int n, int target);

#endif
```

다음으로, ft_printf.c 파일의 함수들을 살펴보겠습니다.




```{c filename=ft_printf.c}
int	ft_printf(const char *s, ...)
{
	va_list	ap;
	int		cnt;
	int		tmp;

	va_start(ap, s); # 변수 초기화
	cnt = 0;
	while (*s != '\0')
	{
		if (*s == '%') # format 문자를 만날 경우
		{
			s++;
			tmp = ft_convert(&ap, &s); # format 문자를 ft_convert 함수에서 처리해줍니다.
		}
		else
			tmp = write(1, s, 1); # format 문자가 아닐 경우 그대로 출력합니다.
		if (tmp < 0)
			return (-1); # 출력에 실패하면 -1을 반환합니다. 동적할당을 하지 않았기때문에 다른 조치는 취하지 않습니다.
		cnt += tmp; # 출력한 문자 갯수만큼 계속 저장해줍니다.
		s++;
	}
	va_end(ap);
	return (cnt); # 최종적으로 출력에 성공한 문자의 갯수를 반환합니다.
}
```




```c
/*flag에 대한 정보를 먼저 처리해줍니다.*/
/*코드가 조금 특이하죠. 사실 norminette 때문에 이렇게 구현했습니다.*/
static int	ft_convert(va_list *ap, const char **s)
{
	t_info	i;
	int		tmp;

	i.flag = 0; # 변수들을 초기화 해줍니다.
	i.cnt = 0;
	i.field[0] = 0;
	i.field[1] = 0;
	while (**s == '#' || **s == ' ' || **s == '0' || **s == '-' || **s == '+')
	{
		tmp = "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!0!!1!!!!!!!2!3!!4"[(int)**s];
		i.flag |= (1 << (tmp - '0'));
		(*s)++;
	}
	while (**s == '.' || (**s >= '1' && **s <= '9'))
	{
		tmp = (**s == '.');
		(*s) += tmp;
		i.flag |= (F_WDTH >> tmp);
		while (**s >= '0' && **s <= '9')
		{
			i.field[tmp] = i.field[tmp] * 10 + (**s - '0');
			(*s)++;
		}
	}
	return (ft_parse(ap, **s, i));
}
```

이 함수에서 조금 특이한 두 부분을 짚고 넘어가겠습니다.

먼저 flag를 읽는 부분입니다.

```c
tmp = "...0!!1!!!!!!!2!3!!4"[(int)**s];
i.flag |= (1 << (tmp - '0'));
```

flag 문자를 if-else로 일일이 비교하는 대신, 문자의 ASCII 값으로 문자열을 인덱싱했습니다. 공백(32)·`#`(35)·`+`(43)·`-`(45)·`0`(48) 위치에 각각 `'0'`부터 `'4'`까지를 박아 두고 나머지 자리는 `!`로 채운 룩업 테이블입니다. 꺼낸 숫자 `d`로 `1 << d`를 만들면 바로 해당 flag 비트가 됩니다. 분기 없이 두 줄로 끝나서 norminette의 함수 길이 제한에도 유리했습니다.

width와 precision을 읽는 부분도 한 루프로 합쳤습니다.

```c
tmp = (**s == '.');
(*s) += tmp;
i.flag |= (F_WDTH >> tmp);
```

`.`이면 `tmp`가 1, 아니면 0입니다. `F_WDTH`(64)를 `tmp`만큼 오른쪽으로 밀면 width일 때는 64(`F_WDTH`), precision일 때는 32(`F_PREC`)가 되고, 저장 위치도 `field[0]`/`field[1]`로 갈립니다. 같은 코드로 둘 다 처리하는 셈입니다. 바깥 조건이 `**s >= '1'`로 시작하는 이유는, ISO C99가 `0`을 width의 시작이 아니라 flag로 취급하라고 못 박아 두었기 때문입니다(§7.19.6.1, 각주 232).

```c
static void	ft_flag_validate(t_info *i)
{
	if ((i->flag & F_ZERO) && (i->flag & F_LEFT))
		i->flag &= ~F_ZERO;
	if ((i->flag & F_ZERO) && (i->flag & F_PREC))
		i->flag &= ~F_ZERO;
	if ((i->flag & F_SPACE) && (i->flag & F_PLUS))
		i->flag &= ~F_SPACE;
}

/*본격적으로 specifier를 처리해주는 로직입니다.*/
static int	ft_parse(va_list *ap, char c, t_info i)
{
	int	status;

	i.cmd = c;
	ft_flag_validate(&i);
	if (c == 'c')
		status = ft_putchr((char)(va_arg(*ap, size_t)), &i);
	else if (c == '%')
		status = ft_putchr('%', &i);
	else if (c == 's')
		status = ft_printstr(va_arg(*ap, char *), &i);
	else if (c == 'd' || c == 'i')
		status = ft_putnum(va_arg(*ap, int), &i, 0);
	else if (c == 'u')
		status = ft_putnum(va_arg(*ap, unsigned int), &i, 0);
	else if (c == 'p')
		status = ft_puthex((unsigned long long)va_arg(*ap, void *), &i, 0);
	else
		status = ft_puthex(va_arg(*ap, unsigned int), &i, 0);
	if (status < 0 || ft_padding(&i, i.cnt) < 0)
		return (-1);
	return (i.cnt);
}
```

다음으로, parse.c 파일의 함수들입니다.

```c
int	ft_putchr(char c, t_info *i)
{
  /*이 로직은 아래에서 사용됩니다.*/
	if (c == '!' && i->cmd != 'c' && i->cmd != 's')
		return (0);
	if ((i->cmd == 'c' || i->cmd == '%') && !(i->flag & F_LEFT))
		if (ft_padding(i, 1) < 0)
			return (-1);
	i->cnt++;
	return (write(1, &c, 1));
}

int	ft_printstr(char *s, t_info *i)
{
	int	len;

	len = 0;
  /*printf에서는 null이 오면 (null)을 출력한다는 점을 바탕으로 작성했습니다.*/
	if (s == NULL)
		return (ft_printstr("(null)", i));
	while (s[len] && !((i->flag & F_PREC) && len >= i->field[1]))
		len++;
	if (!(i->flag & F_LEFT))
		if (ft_padding(i, len) < 0)
			return (-1);
	len = 0;
	while (s[len] && !((i->flag & F_PREC) && len >= i->field[1]))
	{
		if (ft_putchr(s[len], i) < 0)
			return (-1);
		len++;
	}
	return (0);
}

int	ft_putnum(long long num, t_info *i, int cur)
{
	int	is_sign;
	int	is_put;

	if (num < 0)
		i->flag |= (F_PLUS + F_SPACE);
  /*norminette 때문에 삼항연산자를 쓸 수 없어서 아래와 같이 작성했습니다.*/
	num *= 1 * (num >= 0) + -1 * (num < 0); 
	is_sign = (i->flag & (F_PLUS + F_SPACE)) != 0;
	is_put = !(num == 0 && cur == 0 && i->field[1] == 0 && (i->flag & F_PREC));
	if (num < 10)
	{
		if ((i->flag & F_ZERO) && ft_putchr("! !!+-"[i->flag & 5], i) < 0)
			return (-1);
		if (!(i->flag & F_LEFT))
			if (ft_padding(i, ft_max(cur + is_put, i->field[1]) + is_sign) < 0)
				return (-1);
		if (!(i->flag & F_ZERO) && ft_putchr("! !!+-"[i->flag & 5], i) < 0)
			return (-1);
		if ((i->flag & F_PREC))
			return (ft_precision(i, num, cur, num % 10 + '0'));
		return (ft_putchr(num % 10 + '0', i));
	}
	if (ft_putnum(num / 10, i, cur + 1) < 0 || ft_putchr(num % 10 + '0', i) < 0)
		return (-1);
	return (0);
}

int	ft_puthex(unsigned long long num, t_info *i, int cur)
{
	char	s;
	int		is_sign;

  /* %x나 %p specifier의 경우 소문자로 출력 */
	s = "0123456789ABCDEF"[num % 16] | 32 * (i->cmd == 'x' || i->cmd == 'p');
	is_sign = (i->cmd == 'p' || (!(cur == 0 && num == 0) && (i->flag & 2))) * 2;
	if (num < 16)
	{
		if ((i->flag & F_ZERO) && is_sign != 0)
			if (ft_putchr('0', i) < 0 || ft_putchr("xX"[i->cmd == 'X'], i) < 0)
				return (-1);
		if (!(i->flag & F_LEFT))
			if (ft_padding(i, ft_max(cur + 1, i->field[1]) + is_sign) < 0)
				return (-1);
		if (!(i->flag & F_ZERO) && is_sign != 0)
			if (ft_putchr('0', i) < 0 || ft_putchr("xX"[i->cmd == 'X'], i) < 0)
				return (-1);
		if ((i->flag & F_PREC))
			return (ft_precision(i, num, cur, s));
		return (ft_putchr(s, i));
	}
	if (ft_puthex(num / 16, i, cur + 1) < 0 || ft_putchr(s, i) < 0)
		return (-1);
	return (0);
}
```

parse.c에는 손이 많이 간 부분이 있어 따로 설명하겠습니다.

`ft_putnum`은 부호 있는 정수를 다룹니다. 음수가 들어오면 절댓값을 구해야 하는데, `INT_MIN`(-2147483648)은 `int`로 부호를 뒤집는 순간 오버플로우가 납니다. 그래서 인자를 처음부터 `long long`으로 받고,

```c
num *= 1 * (num >= 0) + -1 * (num < 0);
```

곱셈으로 절댓값을 만들었습니다. norminette에서 삼항연산자를 못 써서 `?:` 대신 이런 모양이 됐습니다.

부호 문자를 고르는 부분도 룩업입니다.

```c
ft_putchr("! !!+-"[i->flag & 5], i)
```

`& 5`는 `F_PLUS`(4)와 `F_SPACE`(1) 비트만 남기므로 인덱스는 0·1·4·5만 나오고, 각각 `!`·공백·`+`·`-`에 대응됩니다. 음수일 때 위에서 `flag |= F_PLUS + F_SPACE`(=5)를 줬기 때문에 자연스럽게 `-`가 선택됩니다. 부호가 없어야 하는 경우의 `!`는 "아무것도 출력하지 않는다"는 약속입니다. `ft_putchr` 맨 위에서 숫자 변환일 때 `!`가 들어오면 0을 반환하도록 해 둬서(앞서 "이 로직은 아래에서 사용됩니다"라고 적어 둔 그 줄입니다), 부호가 없을 때 별도 분기 없이 출력만 건너뜁니다.

`ft_puthex`의 대소문자 처리도 같은 결입니다.

```c
s = "0123456789ABCDEF"[num % 16] | 32 * (i->cmd == 'x' || i->cmd == 'p');
```

ASCII에서 대문자에 32를 OR하면 소문자가 됩니다(`'A' | 32 == 'a'`). 그래서 `%x`·`%p`일 때만 32를 더해 소문자로 출력하고, `%X`는 대문자 그대로 둡니다.

두 함수 모두 자릿수를 재귀로 출력합니다. 가장 큰 자리까지 내려간 다음 돌아 나오면서 한 자리씩 찍기 때문에, 버퍼 배열 없이도 올바른 순서가 나옵니다. 인자 `cur`는 지금 몇 번째 자리인지를 들고 다니며 padding과 precision 계산에 쓰입니다.

마지막으로 flag_utils.c 함수입니다.

```c
#include "ft_printf.h"

int	ft_max(int a, int b)
{
	if (a >= b)
		return (a);
	return (b);
}

int	ft_padding(t_info *i, int n)
{
	char	padding;

	padding = ' ';
	if (i->flag & F_ZERO)
		padding = '0';
	while ((i->flag & F_WDTH) && n < i->field[0])
	{
		if (write(1, &padding, 1) < 0)
			return (-1);
		i->cnt++;
		n++;
	}
	return (0);
}

int	ft_precision(t_info *i, int num, int n, int target)
{
	if (num == 0 && n == 0 && i->field[1] == 0)
		return (0);
	while ((i->flag & F_PREC) && n < i->field[1] - 1)
	{
		if (ft_putchr('0', i) < 0)
			return (-1);
		n++;
	}
	return (ft_putchr(target, i));
}
```

## Edge case와 표준 근거

애매한 동작은 전부 ISO C99 §7.19.6.1을 기준으로 정했습니다. 코드 일부는 사실상 표준 문장을 그대로 옮긴 것이라, 근거와 함께 정리해 둡니다.

### flag 충돌 처리는 표준 그대로입니다

`ft_flag_validate`의 세 줄은 제가 임의로 정한 규칙이 아닙니다.

- `0`과 `-`가 같이 오면 `0`을 무시하고, `d,i,u,x,X`에서 precision이 있으면 `0`을 무시 → para 6 `0`: "If the 0 and - flags both appear, the 0 flag is ignored. ... if a precision is specified, the 0 flag is ignored."
- 공백과 `+`가 같이 오면 공백을 무시 → para 6 space: "If the space and + flags both appear, the space flag is ignored."

### 0과 precision이 얽힌 경우

- `%.0d`에 `0`을 넘기면 아무것도 출력하지 않습니다 → para 8 `d,i`: "The result of converting a zero value with a precision of zero is no characters." `is_put`과 `ft_precision`이 이 경우를 걸러냅니다.
- `%#x`에 `0`을 넘기면 `0x` 접두사가 붙지 않습니다 → para 6 `#`: 접두사는 "a nonzero result"에만 붙습니다. `is_sign`의 `!(cur == 0 && num == 0)` 조건이 이 부분입니다.
- precision이 `.`만 있고 숫자가 없으면 0으로 취급합니다 → para 4: "if only the period is specified, the precision is taken as zero."

### 구현 정의(implementation-defined) 영역

표준이 정해주지 않아 제가 선택한 부분입니다. 정직하게 밝혀 둡니다.

- `%p`의 출력 형식은 표준이 정하지 않습니다 → para 8 `p`: "converted to a sequence of printing characters, in an implementation-defined manner." NULL을 `0x0`으로 찍는 것, 소문자 16진수, `0x` 접두사 모두 표준 의무가 아니라 제 선택입니다. (리눅스 glibc는 NULL을 `(nil)`로 출력합니다.)
- `%s`에 `NULL`을 넘기는 것은 엄밀히는 표준상 정의되지 않은 동작입니다 → para 8 `s`는 인자가 문자 배열을 가리켜야 한다고만 합니다. `(null)` 출력은 표준이 보장하는 게 아니라 흔한 구현 관례를 따른 것입니다.
- 정의되지 않은 specifier(예: `%z`)는 `else`로 흘러가 16진수처럼 처리됩니다 → para 9: "If a conversion specification is invalid, the behavior is undefined." 어차피 UB라 동작이 자유롭습니다.

### 일부러 구현하지 않은 것

과제 범위를 벗어나 의도적으로 뺀 부분입니다(못 한 게 아니라 안 한 것입니다).

- length modifier(`h`, `l`, `ll`, `hh` 등) — para 7. 과제가 요구하지 않습니다.
- `*`로 width/precision을 인자로 받는 형태 — para 5. 마찬가지로 범위 밖입니다.

반환값은 para 14를 따릅니다. 출력한 문자 수를 반환하고, 출력 중 오류가 나면 음수를 반환합니다. 또 para 10에 따라 field width가 실제 출력보다 작아도 결과가 잘리지 않습니다.

